declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('wedding_vows.view');$conn->set_charset('utf8mb4');$id=cb_int($_GET['id']??0);$r=$id>0?cb_fetch_one($conn,"SELECT * FROM wedding_vows WHERE id=?",'i',[$id]):null;if(!$r){http_response_code(404);exit('Wedding record not found.');}$site=cb_site_setting($conn,'site_name','Church Management System');
?><!doctype html><html><head><meta charset="utf-8"><title>Wedding Vows Record</title><style>body{font-family:Georgia,'Times New Roman',serif;color:#111;margin:35px auto;max-width:850px;padding:0 22px}.actions{text-align:right}h1,h2,p{text-align:center;margin:5px}.rule{border-top:2px solid #111;margin:14px 0 22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 28px}.item{padding:7px 0;border-bottom:1px dotted #999}.item b{display:block;font:11px Arial,sans-serif;text-transform:uppercase;color:#555;margin-bottom:4px}.wide{grid-column:1/-1}.vows{margin:22px 0;padding:18px;border:1px solid #aaa;min-height:120px;white-space:pre-wrap}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:55px 35px;margin-top:55px}.sig{border-top:1px solid #111;padding-top:6px;text-align:center;font-size:12px}@media print{.actions{display:none}body{margin:0 auto}}</style></head><body><div class="actions"><button onclick="window.print()">Print Record</button></div><h2><?= cb_h($site) ?></h2><h1>Wedding Vows Record</h1><p>Register No: <?= cb_h($r['register_no']?:'—') ?> &nbsp; | &nbsp; Certificate No: <?= cb_h($r['certificate_no']?:'—') ?></p><div class="rule"></div><div class="grid"><div class="item"><b>Wedding Date</b><?= cb_h(date('d F Y',strtotime($r['wedding_date']))) ?></div><div class="item"><b>Venue</b><?= cb_h($r['venue']?:'—') ?></div><div class="item"><b>Groom</b><?= cb_h($r['groom_name']) ?></div><div class="item"><b>Bride</b><?= cb_h($r['bride_name']) ?></div><div class="item"><b>Groom's Parents</b><?= cb_h(trim(($r['groom_father']?:'').' / '.($r['groom_mother']?:''),' /')) ?></div><div class="item"><b>Bride's Parents</b><?= cb_h(trim(($r['bride_father']?:'').' / '.($r['bride_mother']?:''),' /')) ?></div><div class="item"><b>Ceremony Basis</b><?= cb_h($r['ceremony_type']) ?><?= $r['marriage_licence_no']?' · '.cb_h($r['marriage_licence_no']):'' ?></div><div class="item"><b>Status</b><?= cb_h($r['status']) ?></div><div class="item"><b>Witness 1</b><?= cb_h($r['witness_1']?:'—') ?></div><div class="item"><b>Witness 2</b><?= cb_h($r['witness_2']?:'—') ?></div><div class="item"><b>Officiating Minister</b><?= cb_h($r['officiant']?:'—') ?></div><div class="item"><b>Assisting Minister</b><?= cb_h($r['assisting_minister']?:'—') ?></div><div class="item wide"><b>Scripture / Theme</b><?= cb_h($r['scripture_theme']?:'—') ?></div></div><h3 style="text-align:center;margin-top:28px">Vows / Declaration</h3><div class="vows"><?= cb_h($r['vows_text']?:'') ?></div><div class="signatures"><?php foreach(cb_wedding_signature_lines($conn) as $sigLabel):?><div class="sig"><?= cb_h($sigLabel) ?></div><?php endforeach;?></div><?php if($r['remarks']):?><p style="text-align:left;margin-top:35px"><strong>Remarks:</strong> <?= nl2br(cb_h($r['remarks'])) ?></p><?php endif;?></body></html>
